import argparse

def createparser():
    parser = argparse.ArgumentParser(prog='pysemver', description='Semantic Versioning tool')
    subparsers = parser.add_subparsers(dest='command', required=True)
    # bump
    bump = subparsers.add_parser('bump', help='Bump a version')
    bump.add_argument('component', choices=['major','minor','patch','prerelease','build'])
    bump.add_argument('version')
    # compare
    compare = subparsers.add_parser('compare', help='Compare two versions')
    compare.add_argument('v1')
    compare.add_argument('v2')
    # match
    match = subparsers.add_parser('match', help='Match version against expression')
    match.add_argument('version')
    match.add_argument('expr')
    # replace
    replace = subparsers.add_parser('replace', help='Replace components')
    replace.add_argument('version')
    replace.add_argument('--major', type=int)
    replace.add_argument('--minor', type=int)
    replace.add_argument('--patch', type=int)
    replace.add_argument('--prerelease')
    replace.add_argument('--build')
    return parser

def process(args):
    parser = createparser()
    parsed = parser.parse_args(args)
    if parsed.command == 'bump':
        comp = parsed.component
        ver = parsed.version
        if comp=='major':
            return bump_major(ver)
        elif comp=='minor':
            return bump_minor(ver)
        elif comp=='patch':
            return bump_patch(ver)
        elif comp=='prerelease':
            return bump_prerelease(ver)
        elif comp=='build':
            return bump_build(ver)
    elif parsed.command == 'compare':
        return compare(parsed.v1, parsed.v2)
    elif parsed.command == 'match':
        return match(parsed.version, parsed.expr)
    elif parsed.command == 'replace':
        kwargs={}
        if parsed.major is not None: kwargs['major']=parsed.major
        if parsed.minor is not None: kwargs['minor']=parsed.minor
        if parsed.patch is not None: kwargs['patch']=parsed.patch
        if parsed.prerelease is not None: kwargs['prerelease']=parsed.prerelease
        if parsed.build is not None: kwargs['build']=parsed.build
        return replace(parsed.version, **kwargs)

def main(argv=None):
    import sys
    if argv is None:
        argv = sys.argv[1:]
    result = process(argv)
    if result is not None:
        print(result)
    return result

